import pandas as pd

def find_topic_of_each_post(keywords: pd.DataFrame, posts: pd.DataFrame) -> pd.DataFrame:
    keywords['word_lower'] = keywords['word'].str.lower()
    res = []
    for _, post in posts.iterrows():
        pid = post['post_id']
        words = set(post['content'].lower().split())
        matched_topics = set()
        for _, kw in keywords.iterrows():
            if kw['word_lower'] in words:
                matched_topics.add(kw['topic_id'])
        if matched_topics:
            topic_str = ",".join(str(t) for t in sorted(matched_topics))
        else:
            topic_str = "Ambiguous!"
        res.append({'post_id': pid, 'topic': topic_str})
    return pd.DataFrame(res)
